/bin/bash -lc "cat >> .codex-role-output/checkpoint.md <<'EOF'

Root cause: "'`Convert` replaces `CveContents` for each target and writes only `models.Trivy`; `getCveContents` also writes only `models.Trivy`. Both discard `VendorSeverity` and `CVSS` source maps. Model score readers enumerate fixed types without Trivy source keys, and TUI explicitly reads only `models.Trivy`. Local Trivy types confirm `VendorSeverity map[SourceID]Severity`, `CVSS map[SourceID]CVSS`, and dates on `Vulnerability`.

Hypothesis: building one content per union of severity/CVSS source IDs, merging it by source across targets, then enumerating those types will retain distinct source metadata.
EOF
cat > contrib/trivy/pkg/converter_test.go <<'"'EOF'
package pkg

import (
 \"testing\"
 \"time\"

 dbtypes \"github.com/aquasecurity/trivy-db/pkg/types\"
 ftypes \"github.com/aquasecurity/trivy/pkg/fanal/types\"
 \"github.com/aquasecurity/trivy/pkg/types\"
 \"github.com/future-architect/vuls/models\"
)

func TestConvertPreservesTrivySourcesAcrossTargets(t *testing.T) {
 published := time.Date(2024, 1, 2, 0, 0, 0, 0, time.UTC)
 modified := published.Add(time.Hour)
 results := types.Results{
  {Type: ftypes.Debian, Vulnerabilities: []types.DetectedVulnerability{{VulnerabilityID: \"CVE-2024-1234\", Vulnerability: dbtypes.Vulnerability{Title: \"title\", Description: \"summary\", VendorSeverity: dbtypes.VendorSeverity{\"debian\": dbtypes.SeverityLow, \"nvd\": dbtypes.SeverityHigh}, CVSS: dbtypes.VendorCVSS{\"nvd\": {V3Score: 8.1, V3Vector: \"CVSS:3.1/test\"}}, References: []string{\"https://example.com/ref\"}, PublishedDate: &published, LastModifiedDate: &modified}}}},
  {Type: ftypes.Ubuntu, Vulnerabilities: []types.DetectedVulnerability{{VulnerabilityID: \"CVE-2024-1234\", Vulnerability: dbtypes.Vulnerability{VendorSeverity: dbtypes.VendorSeverity{\"ubuntu\": dbtypes.SeverityMedium}}}}},
 }
 got, err := Convert(results)
 if err "'!= nil { t.Fatal(err) }
 contents := got.ScannedCves["CVE-2024-1234"].CveContents
 for typ, severity := range map[models.CveContentType]string{models.TrivyDebian: "LOW", models.TrivyNVD: "HIGH", models.TrivyUbuntu: "MEDIUM"} {
  if len(contents[typ]) != 1 || contents[typ][0].Cvss3Severity != severity || contents[typ][0].Type != typ || contents[typ][0].CveID != "CVE-2024-1234" { t.Errorf("%s: %+v", typ, contents[typ]) }
 }
 if contents[models.TrivyNVD][0].Cvss3Score != 8.1 || contents[models.TrivyNVD][0].Cvss3Vector != "CVSS:3.1/test" { t.Errorf("NVD CVSS: %+v", contents[models.TrivyNVD]) }
 if !contents[models.TrivyDebian][0].Published.Equal(published) || !contents[models.TrivyDebian][0].LastModified.Equal(modified) { t.Errorf("dates: %+v", contents[models.TrivyDebian]) }
}
EOF
go test -mod=readonly ./contrib/trivy/pkg -run TestConvertPreservesTrivySourcesAcrossTargets -count=1'

